const items = $input.all();

const quarterFocus = {
  1: 'Career Assessment & Objectives',
  2: 'Skill & Leadership Development',
  3: 'Skill & Leadership Development (continued)',
  4: 'Measure of Success & Culture Impact'
};

return items.map(item => {
  const d = item.json;
  const week = parseInt(d.current_week);
  const status = d.cycle_status;
  let action = 'skip';

  if (status === 'no_cycle' || week === 1) {
    action = 'week1';
  } else if (week >= 2 && week <= 9 && status === 'pending') {
    action = 'reminder';
  } else if (week >= 10 && status === 'pending') {
    action = 'escalate';
  }

  return {
    json: {
      ...d,
      _action: action,
      _quarterFocus: quarterFocus[d.current_quarter] || 'Development'
    }
  };
});

const item = $input.item.json;

function makeToken() {
  return [
    Math.random().toString(36).slice(2),
    Math.random().toString(36).slice(2),
    Date.now().toString(36)
  ].join('');
}

const expiry = new Date();
expiry.setDate(expiry.getDate() + 84);

return {
  json: {
    ...item,
    mentee_goal_token: makeToken(),
    mentor_goal_token: makeToken(),
    token_expiry: expiry.toISOString()
  }
};

const cycleRow = $input.item.json;
const prev = $('Generate Goal Tokens').item.json;

const cycle_id = cycleRow.cycle_id || prev.cycle_id;

return {
  json: {
    ...prev,
    cycle_id
  }
};

const item = $input.item.json;

function makeToken() {
