parameters.jsCode:
const allRows = $input.all();
const p = $('Validate Token').first().json;

const qf = {
  1: { name: 'Career Assessment & Objectives', ctx: 'Mentee should have set 1-3 goals aligned with org objectives. Mentor should have guided goal-setting.' },
  2: { name: 'Skill & Leadership Development', ctx: 'Mentee developing skills via 70/20/10 framework. Mentor identifying training resources.' },
  3: { name: 'Skill & Leadership Development (continued)', ctx: 'Mentee applying new skills practically. Mentor reviewing attitude and network building.' },
  4: { name: 'Measure of Success & Culture Impact', ctx: 'Mentee assessing goal achievement. Mentor evaluating overall growth.' }
};

const focus = qf[p.quarter];
let menteeGoals = [], mentorPlan = '';

for (const row of allRows) {
  const r = row.json;
  if (r.submitted_by === 'mentee') {
    if (r.goal_1) menteeGoals.push(r.goal_1);
    if (r.goal_2) menteeGoals.push(r.goal_2);
    if (r.goal_3) menteeGoals.push(r.goal_3);
  }
  if (r.submitted_by === 'mentor') mentorPlan = r.additional_context || '';
}

const gt = menteeGoals.length > 0
  ? menteeGoals.map((g, i) => `${i+1}. ${g}`).join('\n')
  : 'No goals submitted yet.';

const menteePrompt = `You are an HR assistant at Orange Group Nigeria. Generate exactly 7 feedback questions for the MENTEE.\nQuarter: Q${p.quarter} - ${focus.name}\nContext: ${focus.ctx}\nMentee Goals:\n${gt}\nMentor Plan: ${mentorPlan || 'Not submitted'}\nMix scale 1-5 and open text. Return ONLY a JSON array, no markdown:\n[{"question":"...","type":"scale"},{"question":"...","type":"text"}]`;

const mentorPrompt = `You are an HR assistant at Orange Group Nigeria. Generate exactly 6 feedback questions for the MENTOR.\nQuarter: Q${p.quarter} - ${focus.name}\nContext: ${focus.ctx}\nMentee Goals:\n${gt}\nReturn ONLY a JSON array, no markdown:\n[{"question":"...","type":"scale"},{"question":"...","type":"text"}]`;

return {
  json: {
    pairId: p.pair_id,
    cycleId: p.cycle_id,
    quarter: p.quarter,
    menteeName: p.mentee_name,
    menteeEmail: p.mentee_email,
    mentorName: p.mentor_name,
    mentorEmail: p.mentor_email,
    menteePrompt,
    mentorPrompt
  }
};

const p = $('Build AI Prompts').first().json;
const menteeRaw = $('Groq Mentee Questions').first().json?.choices?.[0]?.message?.content || '[]';
const mentorRaw = $('Groq Mentor Questions').first().json?.choices?.[0]?.message?.content || '[]';

const fallback7 = [
  {question:'Rate your overall progress towards your goals this quarter.',type:'scale'},
  {question:'What achievement are you most proud of this quarter?',type:'text'},
  {question:'How effectively did your mentor support you?',type:'scale'},
  {question:'What challenges did you face and how did you handle them?',type:'text'},
  {question:'Rate your confidence going into next quarter.',type:'scale'},
  {question:'What skills did you develop most this quarter?',type:'text'},
  {question:'Rate the overall value of the mentorship program.',type:'scale'}
];
const fallback6 = [
  {question:'Rate your mentee overall progress this quarter.',type:'scale'},
  {question:'What growth did you observe most in your mentee?',type:'text'},
  {question:'How engaged and proactive was your mentee?',type:'scale'},
  {question:'What support did you provide that made the most impact?',type:'text'},
  {question:'How prepared is your mentee for next quarter?',type:'scale'},
  {question:'What should your mentee focus on next quarter?',type:'text'}
];

let meeQs, menQs;
try { meeQs = JSON.parse(menteeRaw.replace(/```json|```/g,'').trim()); } catch(e) { meeQs = fallback7; }
try { menQs = JSON.parse(mentorRaw.replace(/```json|```/g,'').trim()); } catch(e) { menQs = fallback6; }

function tok() {
  return [Math.random().toString(36).slice(2), Math.random().toString(36).slice(2), Date.now().toString(36)].join('');
}
const exp = new Date();
exp.setDate(exp.getDate() + 21);

return {
  json: {
    ...p,
    menteeFeedbackToken: tok(),
    mentorFeedbackToken: tok(),
    menteeQuestions: JSON.stringify(meeQs),
    mentorQuestions: JSON.stringify(menQs),
    tokenExpiry: exp.toISOString()
  }
};

const d = $json;
