const rows = $input.all().map(r => r.json);

// ── Helpers ──────────────────────────────────────────────────────────────────
const statusStyle = {
  pending:      { label: 'Pending',      bg: '#FEF3C7', color: '#92400E' },
  confirmed:    { label: 'Confirmed',    bg: '#dcfce7', color: '#166534' },
  escalated:    { label: 'Escalated',   bg: '#fee2e2', color: '#991b1b' },
  feedback_sent:{ label: 'Feedback Sent',bg: '#DBEAFE', color: '#1e40af' },
  no_cycle:     { label: 'No Cycle',     bg: '#F3F4F6', color: '#6B7280' },
};

const badge = (text, bg, color) =>
  `<span style="background:${bg};color:${color};padding:3px 10px;border-radius:10px;font-size:11px;font-weight:700;white-space:nowrap">${text}</span>`;

const tick = v => v ? '✅' : '⏳';

const now = new Date().toLocaleString('en-GB', {
  timeZone: 'Africa/Lagos', dateStyle: 'full', timeStyle: 'short'
});

// ── MENTEE VIEW DATA ──────────────────────────────────────────────────────────
const totalPairs     = rows.length;
const confirmed      = rows.filter(r => r.cycle_status === 'confirmed' || r.cycle_status === 'feedback_sent').length;
const pending        = rows.filter(r => r.cycle_status === 'pending').length;
const escalated      = rows.filter(r => parseInt(r.escalation_count) > 0).length;
const feedbackDone   = rows.filter(r => parseInt(r.feedback_submitted_count) >= 2).length;

let menteeRows = '';
for (const d of rows) {
  const st  = d.cycle_status || 'no_cycle';
  const s   = statusStyle[st] || statusStyle.no_cycle;
  const fb  = parseInt(d.feedback_submitted_count || 0);
  const esc = parseInt(d.escalation_count || 0);
  menteeRows += `
  <tr>
    <td style="padding:12px 14px">
      <div style="font-weight:600;font-size:13px;color:#111">${d.mentee_name}</div>
      <div style="font-size:11px;color:#9CA3AF">${d.mentee_email}</div>
    </td>
    <td style="padding:12px 14px">
      <div style="font-weight:600;font-size:13px;color:#111">${d.mentor_name || '—'}</div>
      <div style="font-size:11px;color:#9CA3AF">${d.mentor_email || ''}</div>
    </td>
    <td style="padding:12px 14px;text-align:center">
      ${badge(`Q${d.current_quarter} W${d.current_week}`, '#EFF6FF', '#1d4ed8')}
    </td>
    <td style="padding:12px 14px;text-align:center">
      ${badge(s.label, s.bg, s.color)}
      ${esc > 0 ? `<br><span style="margin-top:4px;display:inline-block">${badge('ESCALATED', '#fee2e2', '#991b1b')}</span>` : ''}
    </td>
    <td style="padding:12px 14px;text-align:center;font-size:16px">${tick(d.meeting_confirmed_mentee)}</td>
    <td style="padding:12px 14px;text-align:center;font-size:16px">${tick(d.meeting_confirmed_mentor)}</td>
    <td style="padding:12px 14px;text-align:center">
      <span style="font-size:13px;font-weight:600;color:${fb >= 2 ? '#16a34a' : '#9CA3AF'}">${fb}/2</span>
    </td>
  </tr>`;
}

// ── MENTOR VIEW DATA ──────────────────────────────────────────────────────────
const mentorMap = {};
for (const d of rows) {
  const key = d.mentor_email;
  if (!key) continue;
  if (!mentorMap[key]) {
    mentorMap[key] = {
      mentor_name:  d.mentor_name,
      mentor_email: d.mentor_email,
      mentees: []
    };
  }
  mentorMap[key].mentees.push(d);
}

const mentors = Object.values(mentorMap);

const totalMentors   = mentors.length;
const allConfirmed   = mentors.filter(m =>
  m.mentees.every(d => d.cycle_status === 'confirmed' || d.cycle_status === 'feedback_sent')
).length;
const anyPending     = mentors.filter(m =>
  m.mentees.some(d => d.cycle_status === 'pending' || d.cycle_status === 'no_cycle')
).length;
const allFbDone      = mentors.filter(m =>
  m.mentees.every(d => parseInt(d.feedback_submitted_count) >= 2)
).length;

let mentorRows = '';
for (const m of mentors.sort((a,b) => a.mentor_name.localeCompare(b.mentor_name))) {
  const totalFb    = m.mentees.reduce((s,d) => s + parseInt(d.feedback_submitted_count||0), 0);
  const maxFb      = m.mentees.length * 2;
  const totalEsc   = m.mentees.reduce((s,d) => s + parseInt(d.escalation_count||0), 0);
  const allConf    = m.mentees.every(d => d.meeting_confirmed_mentor);
  const someConf   = m.mentees.some(d => d.meeting_confirmed_mentor);

  const overallStatus = allConf
    ? badge('All Confirmed', '#dcfce7', '#166534')
    : someConf
      ? badge('Partially Confirmed', '#FEF3C7', '#92400E')
      : badge('None Confirmed', '#fee2e2', '#991b1b');

  const menteeList = m.mentees.map(d => {
    const st = d.cycle_status || 'no_cycle';
