      email: d.mentor_email,
      name: d.mentor_name,
      cohort_name: d.cohort_name,
      mentees: []
    };
  }
  mentorMap[d.mentor_email].mentees.push({
    name: d.mentee_name,
    email: d.mentee_email
  });
}

