const d = $input.first().json;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>MentorMe — Mentcolumn_18/title>
  <style>
    * { box-sizing:border-box; margin:0; padding:0; }
    body { font-family:Arial,sans-serif; background:#F3F4F6; min-height:100vh; display:flex; align-items:center; justify-content:center; padding:24px; }
    .card { background:white; border-radius:12px; overflow:hidden; width:100%; max-width:560px; box-shadow:0 4px 20px rgba(0,0,0,0.08); }
    .header { background:#1A1A2E; padding:24px 32px; }
    .header h1 { color:white; font-size:18px; }
    .header p { color:#9CA3AF; font-size:13px; margin-top:4px; }
    .accent { background:#E8671A; height:4px; }
    .body { padding:32px; }
    .prefilled-section { background:#F9FAFB; border:1px solid #E5E7EB; border-radius:8px; padding:16px 20px; margin-bottom:24px; }
    .prefilled-section h3 { font-size:12px; font-weight:700; color:#9CA3AF; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:12px; }
    .prefilled-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
    .prefilled-item label { font-size:11px; color:#9CA3AF; display:block; margin-bottom:2px; }
    .prefilled-item span { font-size:13px; font-weight:600; color:#1A1A2E; }
    .field { margin-bottom:20px; }
    .field label { display:block; font-size:13px; font-weight:600; color:#374151; margin-bottom:6px; }
    .field textarea { width:100%; border:1.5px solid #E5E7EB; border-radius:8px; padding:12px; font-size:14px; font-family:Arial,sans-serif; resize:vertical; min-height:140px; transition:border 0.2s; outline:none; }
    .field textarea:focus { border-color:#E8671A; }
    .hint { font-size:11px; color:#9CA3AF; margin-top:4px; }
    .btn { width:100%; background:#E8671A; color:white; border:none; padding:14px; border-radius:8px; font-size:15px; font-weight:700; cursor:pointer; transition:background 0.2s; }
    .btn:hover { background:#d45e15; }
    .btn:disabled { background:#9CA3AF; cursor:not-allowed; }
    #msg { display:none; text-align:center; padding:16px; border-radius:8px; margin-top:16px; font-size:14px; font-weight:600; }
    .success-msg { background:#dcfce7; color:#166534; }
    .error-msg { background:#fee2e2; color:#991b1b; }
  </style>
</head>
<body>
<div class="card">
  <div class="header">
    <h1>MentorMe — Mentcolumn_18/h1>
    <p>Please submit your personal statement to complete your mentor profile.</p>
  </div>
  <div class="accent"></div>
  <div class="body">
    <div class="prefilled-section">
      <h3>Your Details</h3>
      <div class="prefilled-grid">
        <div class="prefilled-item"><label>Name</label><span>${d.name || '—'}</span></div>
        <div class="prefilled-item"><label>Email</label><span>${d.person_email || '—'}</span></div>
        <div class="prefilled-item"><label>Department</label><span>${d.department || '—'}</span></div>
        <div class="prefilled-item"><label>Location</label><span>${d.location || '—'}</span></div>
        <div class="prefilled-item"><label>Gender</label><span>${d.gender || '—'}</span></div>
        <div class="prefilled-item"><label>Role</label><span style="text-transform:capitalize">${d.role || '—'}</span></div>
      </div>
    </div>
    <div class="field">
      <label for="statement">Personal Statement / Motivation *</label>
      <textarea id="statement" placeholder="Share your motivation for being a mentor, your mentoring style, areas of expertise you can offer, and what mentees can expect from table_21 with you..."></textarea>
      <p class="hint">Mentees will read this when selecting their mentor. Be authentic and specific.</p>
    </div>
    <button class="btn" id="submitBtn" onclick="submitForm()">Submit My Profile</button>
    <div id="msg"></div>
  </div>
</div>
<script>
async function submitForm() {
  const statement = document.getElementById('statement').value.trim();
  const btn = document.getElementById('submitBtn');
  const msg = document.getElementById('msg');
  msg.style.display = 'none';
  if (!statement) {
    msg.className = 'error-msg';
    msg.style.display = 'block';
    msg.textContent = 'Please enter your personal statement before submitting.';
    return;
  }
  btn.disabled = true;
  btn.textContent = 'Submitting...';
  try {
    const res = await fetch('/webhook/mentorme-mentor-profile', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        token: '${d.token}',
        email: '${d.person_email}',
        personal_statement: statement
      })
    });
    const data = await res.json();
    if (data.success) {
      document.body.innerHTML = \`
        <div style="font-family:Arial,sans-serif;background:#F3F4F6;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;">
          <div style="background:white;border-radius:12px;overflow:hidden;max-width:480px;width:100%;box-shadow:0 4px 20px rgba(0,0,0,0.08);text-align:center;">
            <div style="background:#1A1A2E;padding:24px 32px;">
              <h2 style="color:white;margin:0;font-size:18px;">Orange Group MentorMe</h2>
            </div>
            <div style="background:#E8671A;height:4px;"></div>
            <div style="padding:40px 32px;">
              <div style="font-size:48px;margin-bottom:16px;">✅</div>
              <h2 style="color:#1A1A2E;margin-bottom:12px;">Profile Submitted!</h2>
              <p style="color:#6B7280;font-size:14px;line-height:1.6;">Thank you, ${d.name}. Your mentor profile has been recorded. Mentees will be able to view your profile when selecting their mentor.</p>
            </div>
            <div style="background:#f9f9f9;padding:16px 32px;border-top:1px solid #F3F4F6;">
              <p style="color:#9CA3AF;font-size:12px;margin:0;">Orange Group MentorMe Program</p>
            </div>
          </div>
        </div>\`;
    } else {
      msg.className = 'error-msg';
      msg.textContent = data.message || 'Submission failed';
      msg.style.display = 'block';
      btn.disabled = false;
      btn.textContent = 'Submit My Profile';
    }
  } catch(e) {
    msg.className = 'error-msg';
    msg.textContent = e.message || 'Something went wrong. Please try again.';
    msg.style.display = 'block';
    btn.disabled = false;
    btn.textContent = 'Submit My Profile';
  }
}
</script>
</body>
</html>`;

return [{ json: { html } }];

